from solution import is_balanced

def test_simple_parens():
    assert is_balanced('()')

def test_nested():
    assert is_balanced('({[]})')

def test_with_text():
    assert is_balanced('func(a[0])')

def test_unmatched_open():
    assert not is_balanced('({')

def test_wrong_order():
    assert not is_balanced('([)]')

def test_empty():
    assert is_balanced('')

def test_only_text():
    assert is_balanced('hello world')
